class KairosHandler(BaseHTTPRequestHandler):
    server_version = "KairosSite/1.0"

    def _send(self, status: int, body: bytes, content_type: str) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store" if content_type.startswith("text/html") else "public, max-age=86400")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "SAMEORIGIN")
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        path = urlparse(self.path).path
        if path in ("/", "/index.html"):
            self._send(200, PAGE.encode("utf-8"), "text/html; charset=utf-8")
        elif path == "/logo.jpg":
            self._send(200, LOGO_BYTES, "image/jpeg")
        elif path == "/health":
            self._send(200, json.dumps({"status": "ok"}).encode(), "application/json")
        else:
            message = f"<h1>404</h1><p>Page introuvable : {html.escape(path)}</p>".encode("utf-8")
            self._send(404, message, "text/html; charset=utf-8")

    def log_message(self, format: str, *args: object) -> None:
        print(f"[Kairos] {self.address_string()} — {format % args}")


def main() -> None:
    parser = argparse.ArgumentParser(description="Site web de Kairos International Ltd")
    parser.add_argument("--host", default=HOST, help="Adresse d'écoute (défaut : 127.0.0.1)")
    parser.add_argument("--port", type=int, default=DEFAULT_PORT, help="Port du serveur (défaut : 8000)")
    parser.add_argument("--no-browser", action="store_true", help="Ne pas ouvrir automatiquement le navigateur")
    args = parser.parse_args()

    server = ThreadingHTTPServer((args.host, args.port), KairosHandler)
    display_host = "127.0.0.1" if args.host in ("0.0.0.0", "::") else args.host
    url = f"http://{display_host}:{args.port}"
    print("\nKairos International — site démarré")
    print(f"Adresse : {url}")
    print("Arrêt : Ctrl+C\n")
    if not args.no_browser:
        threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nArrêt du site Kairos.")
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
